      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.16), transparent 32%),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.12), transparent 28%),
        var(--bg);
      min-height: 100vh;
    }

    .page-shell {
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 40px 20px;
    }

    .support-layout {
      width: min(1040px, 100%);
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      gap: 28px;
      align-items: stretch;
    }

    .panel {
      background: var(--panel);
      backdrop-filter: blur(16px);
      border: 1px solid var(--panel-border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
    }

    .hero-panel {
      padding: 40px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 28px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      width: fit-content;
      padding: 8px 14px;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent-strong);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.02em;
      text-transform: uppercase;
    }

    h1 {
      margin: 18px 0 14px;
      font-size: clamp(2.2rem, 5vw, 3.9rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .hero-copy,
    .hero-list,
    .form-intro,
    .helper-text,
    .error-text,
    .success-message,
    label,
    input,
    button {
      font-size: 1rem;
    }

    .hero-copy,
    .form-intro,
    .helper-text {
      color: var(--muted);
      line-height: 1.7;
    }

    .hero-list {
      display: grid;
      gap: 14px;
    }

    .hero-item {
      display: flex;
      gap: 14px;
      align-items: flex-start;
      padding: 16px 18px;
      background: rgba(255, 255, 255, 0.7);
      border: 1px solid rgba(148, 163, 184, 0.18);
      border-radius: 18px;
    }

    .hero-item strong {
      display: block;
      margin-bottom: 4px;
    }

    .hero-icon {
      width: 40px;
      height: 40px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      border-radius: 14px;
      background: var(--accent-soft);
      color: var(--accent-strong);
      font-weight: 700;
      flex: 0 0 auto;
    }

    .form-panel {
      padding: 36px;
    }

    .form-panel h2 {
      margin: 0 0 8px;
      font-size: 1.7rem;
      letter-spacing: -0.03em;
    }

    .contact-form {
      margin-top: 26px;
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      color: var(--text);
    }

    .required-indicator {
      color: var(--accent-strong);
    }

    input {
      width: 100%;
      border: 1px solid rgba(148, 163, 184, 0.34);
      background: rgba(255, 255, 255, 0.96);
      color: var(--text);
      border-radius: 16px;
      padding: 15px 16px;
      outline: none;
      transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
    }

    input::placeholder {
      color: #94a3b8;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
      transform: translateY(-1px);
    }

    input[aria-invalid="true"] {
      border-color: rgba(220, 38, 38, 0.8);
      box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.1);
    }

    .helper-text,
    .error-text,
    .success-message {
      margin: 0;
    }

    .helper-text {
      font-size: 0.92rem;
    }

    .error-text {
      color: var(--error);
      min-height: 1.3em;
      font-size: 0.92rem;
    }

    .success-message {
      padding: 14px 16px;
      border-radius: 16px;
      background: rgba(34, 197, 94, 0.12);
      color: #166534;
      font-weight: 600;
    }

    .submit-button {
      appearance: none;
      border: 0;
      border-radius: 16px;
      padding: 16px 20px;
      background: linear-gradient(135deg, var(--accent), #0ea5e9);
      color: #ffffff;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
      box-shadow: 0 16px 30px rgba(37, 99, 235, 0.22);
    }

    .submit-button:hover {
      transform: translateY(-1px);
      filter: brightness(1.02);
    }

    .submit-button:active {
      transform: translateY(0);
    }

    @media (max-width: 880px) {
      .support-layout {
        grid-template-columns: 1fr;
      }

      .hero-panel,
      .form-panel {
        padding: 28px;
      }
    }

    @media (max-width: 540px) {
      .page-shell {
        padding: 20px 14px;
      }

      .hero-panel,
      .form-panel {
        padding: 22px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const root = document.getElementById("app");

    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitAttempted: false,
      success: false
    };

    const fields = {
      fullName: {
        id: "full-name",
        label: "Full name",
        placeholder: "Jane Doe",
        required: true,
        type: "text"
      },
      email: {
        id: "email-address",
        label: "Email address",
        placeholder: "jane@company.com",
        required: true,
        type: "email"
      },
      phone: {
        id: "phone-number",
        label: "Phone number",
        placeholder: "(555) 123-4567",
        required: false,
        type: "tel",
        helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567."
      }
    };

    function validateField(name, value) {
      const trimmed = value.trim();

      if (name === "fullName") {
        if (!trimmed) {
          return "Please enter your full name.";
        }
        return "";
      }

      if (name === "email") {
        if (!trimmed) {
          return "Please enter your email address.";
        }

        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(trimmed)) {
          return "Please enter a valid email address.";
        }

        return "";
      }

      if (name === "phone" && trimmed) {
        const phonePattern = /^[+]?[\d\s().-]{7,20}$/;
        if (!phonePattern.test(trimmed)) {
          return "Please use the requested phone number format.";
        }
      }

      return "";
    }

    function getErrors() {
      return {
        fullName: validateField("fullName", state.values.fullName),
        email: validateField("email", state.values.email),
        phone: validateField("phone", state.values.phone)
      };
    }

    function shouldShowError(name, errors) {
      return (state.submitAttempted || state.touched[name]) && Boolean(errors[name]);
    }

    function FormField(name, errors) {
      const config = fields[name];
      const error = shouldShowError(name, errors) ? errors[name] : "";
      const helperId = config.helperText ? config.id + "-helper" : "";
      const errorId = config.id + "-error";
      const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${config.id}">
            ${config.label}${config.required ? ' <span class="required-indicator">*</span>' : ""}
          </label>
          <input
            id="${config.id}"
            name="${name}"
            type="${config.type}"
            placeholder="${config.placeholder}"
            value="${escapeHtml(state.values[name])}"
            ${config.required ? "required" : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            aria-invalid="${error ? "true" : "false"}"
          />
          ${config.helperText ? `<p class="helper-text" id="${helperId}">${config.helperText}</p>` : ""}
          <p class="error-text" id="${errorId}" aria-live="polite">${error}</p>
        </div>
      `;
    }

    function SupportHero() {
      return `
        <section class="panel hero-panel" aria-label="Support overview">
          <div>
            <div class="eyebrow">Support team</div>
            <h1>Get help from the people behind your product.</h1>
            <p class="hero-copy">
              Share your question and our support specialists will follow up with the right next step, guidance, or account help.
            </p>
          </div>

          <div class="hero-list">
            <div class="hero-item">
              <div class="hero-icon">24</div>
              <div>
                <strong>Fast follow-up</strong>
                Typical first responses arrive within one business day.
              </div>
            </div>
            <div class="hero-item">
              <div class="hero-icon">AI</div>
              <div>
                <strong>Product-savvy support</strong>
                Reach a team that understands setup, billing, and day-to-day usage.
              </div>
            </div>
          </div>
        </section>
      `;
    }

    function ContactForm() {
      const errors = getErrors();
      return `
        <section class="panel form-panel" aria-labelledby="contact-form-title">
          <h2 id="contact-form-title">Contact support</h2>
          <p class="form-intro">
            Tell us how to reach you and we will get back to you as soon as possible.
          </p>
          <form class="contact-form" id="contact-form" novalidate>
            ${state.success ? '<p class="success-message" role="status">Thanks. Your message details are ready to be sent to support.</p>' : ""}
            ${FormField("fullName", errors)}
            ${FormField("email", errors)}
            ${FormField("phone", errors)}
            <button class="submit-button" type="submit">Submit request</button>
          </form>
        </section>
      `;
    }

    function App() {
      return `
        <main class="page-shell">
          <div class="support-layout">
            ${SupportHero()}
            ${ContactForm()}
          </div>
        </main>
      `;
    }

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function render() {
      root.innerHTML = App();

      const form = document.getElementById("contact-form");
      const inputs = form.querySelectorAll("input");

      inputs.forEach((input) => {
        input.addEventListener("input", handleInput);
        input.addEventListener("blur", handleBlur);
      });

      form.addEventListener("submit", handleSubmit);
    }

    function handleInput(event) {
      const { name, value } = event.target;
      state.values[name] = value;
      state.success = false;
      render();
      restoreFocus(name);
    }

    function handleBlur(event) {
      const { name } = event.target;
      state.touched[name] = true;
      render();
      restoreFocus(name);
    }

    function handleSubmit(event) {
      event.preventDefault();
      state.submitAttempted = true;
      state.touched.fullName = true;
      state.touched.email = true;
      state.touched.phone = true;

      const errors = getErrors();
      const hasErrors = Object.values(errors).some(Boolean);

      if (!hasErrors) {
        state.success = true;
      }

      render();

      if (hasErrors) {
        const firstErrorField = Object.keys(errors).find((key) => errors[key]);
        restoreFocus(firstErrorField);
      }
    }

    function restoreFocus(name) {
      if (!name) {
        return;
      }
      const field = document.querySelector(`[name="${name}"]`);
      if (field) {
        field.focus();
        const valueLength = field.value.length;
        field.setSelectionRange(valueLength, valueLength);
      }
    }

    render();
  </script>
</body>
