        email: "",
        phone: ""
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitAttempted: false,
      success: false
    };

    const fields = {
      fullName: {
        id: "full-name",
        label: "Full name",
        placeholder: "Jane Doe",
        required: true,
        type: "text"
      },
      email: {
        id: "email-address",
        label: "Email address",
        placeholder: "jane@company.com",
        required: true,
        type: "email"
      },
      phone: {
        id: "phone-number",
        label: "Phone number",
        placeholder: "(555) 123-4567",
        required: false,
        type: "tel",
        helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567."
      }
    };

    function validateField(name, value) {
      const trimmed = value.trim();

      if (name === "fullName") {
        if (!trimmed) {
          return "Please enter your full name.";
        }
        return "";
      }

      if (name === "email") {
        if (!trimmed) {
          return "Please enter your email address.";
        }

        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(trimmed)) {
          return "Please enter a valid email address.";
        }

        return "";
      }

      if (name === "phone" && trimmed) {
        const phonePattern = /^[+]?[\d\s().-]{7,20}$/;
        if (!phonePattern.test(trimmed)) {
          return "Please use the requested phone number format.";
        }
      }

      return "";
    }

