          </label>
          <input
            id="${config.id}"
            name="${name}"
            type="${config.type}"
            placeholder="${config.placeholder}"
            value="${escapeHtml(state.values[name])}"
            ${config.required ? "required" : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            aria-invalid="${error ? "true" : "false"}"
          />
          ${config.helperText ? `<p class="helper-text" id="${helperId}">${config.helperText}</p>` : ""}
          <p class="error-text" id="${errorId}" aria-live="polite">${error}</p>
        </div>
      `;
    }

    function SupportHero() {
      return `
        <section class="panel hero-panel" aria-label="Support overview">
          <div>
            <div class="eyebrow">Support team</div>
            <h1>Get help from the people behind your product.</h1>
            <p class="hero-copy">
              Share your question and our support specialists will follow up with the right next step, guidance, or account help.
            </p>
          </div>

          <div class="hero-list">
            <div class="hero-item">
              <div class="hero-icon">24</div>
              <div>
                <strong>Fast follow-up</strong>
                Typical first responses arrive within one business day.
              </div>
            </div>
            <div class="hero-item">
              <div class="hero-icon">AI</div>
              <div>
                <strong>Product-savvy support</strong>
                Reach a team that understands setup, billing, and day-to-day usage.
              </div>
            </div>
          </div>
        </section>
      `;
    }

    function ContactForm() {
      const errors = getErrors();
      return `
        <section class="panel form-panel" aria-labelledby="contact-form-title">
          <h2 id="contact-form-title">Contact support</h2>
          <p class="form-intro">
            Tell us how to reach you and we will get back to you as soon as possible.
          </p>
          <form class="contact-form" id="contact-form" novalidate>
            ${state.success ? '<p class="success-message" role="status">Thanks. Your message details are ready to be sent to support.</p>' : ""}
            ${FormField("fullName", errors)}
            ${FormField("email", errors)}
            ${FormField("phone", errors)}
            <button class="submit-button" type="submit">Submit request</button>
          </form>
        </section>
      `;
    }

